import { ChangeEvent, useState } from "react";
import { useHistory } from "react-router-dom";
import { Button, Form, Input, InputNumber, notification, Select } from "antd";
import { RegisterCourse } from "../models/course";
import { Content } from "antd/lib/layout/layout";
import { useAppSelector } from "../redux/store/configureStore";
import { categoriesSelector } from "../redux/slice/categorySlice";
import { Category } from "../models/category";
import agent from "../actions/agent";

const CreateCourse = () => {
  const [values, setValues] = useState<RegisterCourse>({
    title: "",
    subTitle: "",
    description: "",
    price: 0,
    categoryId: 0,
    level: "",
    language: "",
  });

  const { title, subTitle, description, price, categoryId, level, language } =
    values;

  const history = useHistory();

  const categories = useAppSelector(categoriesSelector.selectAll);

  const getSelectCategories = () => {
    const catArr: { value: number; label: string }[] = [];

    if (categories) {
      categories.forEach((category: Category) => {
        catArr.push({ value: category.id, label: category.name });
      });
    }

    return catArr;
  };

  const { Option } = Select;

  const [form] = Form.useForm();

  const formItemLayout = {
    labelCol: {
      xs: { span: 24 },
      sm: { span: 8 },
    },
    wrapperCol: {
      xs: { span: 24 },
      sm: { span: 16 },
    },
  };

  const handleChange = (
    e: ChangeEvent<HTMLInputElement | HTMLTextAreaElement>
  ) => {
    const { name, value } = e.target;
    setValues({ ...values, [name]: value });
  };

  const onSubmit = async () => {
    const response = await agent.Courses.create(values);
    notification.success({
      message: response
    });
    history.push("/instructor");
  }

  return (
    <Content style={{ padding: "50px" }}>
      <h1>Create Course</h1>
      <Form {...formItemLayout} form={form} name="course" onFinish={onSubmit}>
        <Form.Item
          name="title"
          label="Course Title"
          rules={[
            {
              min: 10,
              message: "Title should have at least 10 characters",
            },
            {
              required: true,
              message: "Please add title of the course",
            },
          ]}
        >
          <Input onChange={handleChange} name="title" value={title} />
        </Form.Item>
        <Form.Item
          name="subTitle"
          label="Course SubTitle"
          rules={[
            {
              min: 10,
              message: "SubTitle should have at least 10 characters",
            },
            {
              required: true,
              message: "Please add subtitle of the course",
            },
          ]}
        >
          <Input onChange={handleChange} name="subTitle" value={subTitle} />
        </Form.Item>
        <Form.Item
          name="description"
          label="Course Description"
          rules={[
            {
              min: 10,
              message: "Description should have at least 10 characters",
            },
            {
              required: true,
              message: "Please add description of the course",
            },
          ]}
        >
          <Input.TextArea
            onChange={handleChange}
            name="description"
            value={description}
          />
        </Form.Item>
        <Form.Item
          name="price"
          label="Price"
          rules={[
            {
              required: true,
              message: "Please add price of the course",
            },
          ]}
        >
          <InputNumber
            placeholder="Course Price"
            onChange={(value) => setValues({ ...values, price: value })}
            name="price"
            value={price}
          />
        </Form.Item>
        <Form.Item
          name="category"
          label="Course Category"
          rules={[
            {
              required: true,
              message: "Please choose the category of the course",
            },
          ]}
        >
          <Select
            options={getSelectCategories()}
            value={categoryId}
            placeholder="Select the Category"
            onChange={(value) => setValues({ ...values, categoryId: value })}
          />
        </Form.Item>
        <Form.Item
          name="level"
          label="Course Level"
          rules={[
            {
              required: true,
              message: "Please choose a level of the course",
            },
          ]}
        >
          <Select
            value={level}
            placeholder="Choose a level"
            onChange={(value) => setValues({ ...values, level: value })}
          >
            <Option value="Beginner">Beginner</Option>
            <Option value="Intermediate">Intermediate</Option>
            <Option value="Advanced">Advanced</Option>
          </Select>
        </Form.Item>
        <Form.Item
          name="language"
          label="Course Language"
          rules={[
            {
              required: true,
              message: "Please choose a language of the course",
            },
          ]}
        >
          <Select
            value={language}
            placeholder="Choose a language"
            onChange={(value) => setValues({ ...values, language: value })}
          >
            <Option value="English">English</Option>
            <Option value="Spanish">Spanish</Option>
            <Option value="French">French</Option>
            <Option value="Italian">Italian</Option>
            <Option value="Hindi">Hindi</Option>
            <Option value="Japanese">Japanese</Option>
          </Select>
        </Form.Item>
        <Form.Item>
          <Button type="primary" onClick={onSubmit}>Submit</Button>
        </Form.Item>
      </Form>
    </Content>
  );
};

export default CreateCourse;
