import { ChangeEvent, SyntheticEvent, useState } from "react";
import { Card, Typography, Form, Input, Button, notification } from "antd";
import { Content } from "antd/lib/layout/layout";
import { Register } from "../models/user";
import { useAppDispatch } from "../redux/store/configureStore";
import { registerUser } from "../redux/slice/userSlice";
import { useHistory } from "react-router-dom";

interface Props {
  toggleRegister: () => void;
}

const RegisterPage = ({ toggleRegister }: Props) => {
  const [values, setValues] = useState<Register>({
    email: "",
    password: "",
    username: "",
  });

  const { Title, Text } = Typography;

  const { email, password, username } = values;

  const dispatch = useAppDispatch();

  const history = useHistory();

  const [form] = Form.useForm();

  const handleChange = (e: ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setValues({ ...values, [name]: value });
  };

  const resetForm = () => {
    setValues({ ...values, email: "", password: "", username: "" });
    form.resetFields();
  };

  const submitUser = async (e: SyntheticEvent) => {
    e.preventDefault();
    try {
      if (
        email.match(/^[^\s@]+@[^\s@]+\.[^\s@]+$/) &&
        password.length >= 6 &&
        username.length >= 5
      ) {
        await dispatch(registerUser(values));
        history.push("/profile");
      }
      resetForm();
    } catch (error: any) {
      if (error.error) {
        for (const val of error.error) {
          notification.error({
            message: val
          })
        }
      }
      resetForm();
    }
  };

  return (
    <Card className="log-in-card">
      <div className="log-in-card__intro">
        <Typography>
          <Title level={2} className="log-in-card__intro-title">
            Sign up with Learnify
          </Title>
          <Text>Use your username, email and password to Register!</Text>
        </Typography>
      </div>
      <Content className="log-in__form">
        <Form
          name="login"
          labelCol={{ span: 8 }}
          wrapperCol={{ span: 16 }}
          autoComplete="off"
          onSubmitCapture={submitUser}
          form={form}
        >
          <Form.Item
            label="Username"
            name="username"
            rules={[
              {
                required: true,
                message: "Please enter a valid username",
                min: 5,
              },
            ]}
          >
            <Input
              value={username}
              name="username"
              onChange={handleChange}
              autoComplete="off"
            ></Input>
          </Form.Item>
          <Form.Item
            label="Email"
            name="email"
            rules={[
              {
                required: true,
                message: "Please enter a valid email",
                pattern: /^[^\s@]+@[^\s@]+\.[^\s@]+$/,
              },
            ]}
          >
            <Input
              value={email}
              name="email"
              onChange={handleChange}
              autoComplete="off"
            ></Input>
          </Form.Item>
          <Form.Item
            label="Password"
            name="password"
            rules={[
              {
                required: true,
                message: "Please enter a valid password",
                min: 6,
              },
            ]}
          >
            <Input.Password
              value={password}
              name="password"
              onChange={handleChange}
              autoComplete="off"
            ></Input.Password>
          </Form.Item>
          <Form.Item wrapperCol={{ offset: 4, span: 16 }}>
            <Button type="primary" htmlType="submit" onClick={submitUser}>
              Submit
            </Button>
          </Form.Item>
        </Form>
      </Content>
      <div onClick={toggleRegister} className="log-in-card__toggle">
        Already a user? Sign in here.
      </div>
    </Card>
  );
};

export default RegisterPage;
